//! The text of the generated files: the Rust table and the Markdown report.

use std::fmt::Write;
use std::time::Duration;

use oxysol_core::Variant;
use oxysol_core::curated::PER_LEVEL;

use super::run_time_text;
use super::scan::VariantScan;
use super::score::{LEVELS, name};

const LEVEL_NAMES: [&str; LEVELS] = ["very easy", "easy", "medium", "hard", "very hard"];

const TABLE_HEAD: &str = "//! The curated seed table. Generated by `cargo xtask-art curated-seeds` (decision T-49); do not edit
//! by hand. Empty until the generator has run.

use super::PER_LEVEL;
use crate::game::{DrawCount, PyramidRules, SuitCount, Variant, YukonRules};

/// Three seeds for each of the five levels, easiest first.
pub(super) type Levels = [[u64; PER_LEVEL]; 5];

const TABLE: &[(Variant, Levels)] = &[
";

const TABLE_TAIL: &str = "];

/// The levels of `variant`, when the table has them.
pub(super) fn levels(variant: Variant) -> Option<&'static Levels> {
    TABLE
        .iter()
        .find(|(entry, _)| *entry == variant)
        .map(|(_, levels)| levels)
}
";

/// The Rust path of `variant` in the generated table.
fn variant_expr(variant: Variant) -> String {
    match variant {
        Variant::Klondike(draw) => format!("Variant::Klondike(DrawCount::{draw:?})"),
        Variant::Spider(suits) => format!("Variant::Spider(SuitCount::{suits:?})"),
        Variant::FreeCell => "Variant::FreeCell".to_owned(),
        Variant::Pyramid(rules) => format!("Variant::Pyramid(PyramidRules::{rules:?})"),
        Variant::Yukon(rules) => format!("Variant::Yukon(YukonRules::{rules:?})"),
        Variant::Golf => "Variant::Golf".to_owned(),
    }
}

/// The complete `table.rs`, one entry per scanned variant in `Variant::ALL` order.
pub fn table(scans: &[VariantScan]) -> String {
    let mut out = String::from(TABLE_HEAD);
    for scan in scans {
        let _ = writeln!(
            out,
            "    (\n        {},\n        [",
            variant_expr(scan.variant)
        );
        for level in 0..LEVELS {
            let seeds: Vec<String> = (0..PER_LEVEL)
                .map(|slot| scan.pick(level, slot).candidate.seed.to_string())
                .collect();
            let _ = writeln!(out, "            [{}],", seeds.join(", "));
        }
        out.push_str("        ],\n    ),\n");
    }
    out.push_str(TABLE_TAIL);
    out
}

/// One line for the console: the pool size and the scanned seed range of a variant.
pub fn summary_line(scan: &VariantScan) -> String {
    format!(
        "{}: pool {} winnable, scanned seeds 0..={}",
        name(scan.variant),
        scan.sorted.len(),
        scan.scanned_to
    )
}

/// The Markdown report: the method, then per variant the pool and the chosen seeds with E, L, H, D.
pub fn report(scans: &[VariantScan], elapsed: Duration) -> String {
    let mut out = String::new();
    out.push_str(REPORT_INTRO);
    let _ = writeln!(
        out,
        "- Run time of this generation: {}.\n",
        run_time_text(elapsed)
    );
    for scan in scans {
        variant_section(&mut out, scan);
    }
    out
}

fn variant_section(out: &mut String, scan: &VariantScan) {
    let _ = writeln!(out, "## {}\n", name(scan.variant));
    let _ = writeln!(
        out,
        "Pool: {} winnable seeds; scanned seeds 0 to {}.\n",
        scan.sorted.len(),
        scan.scanned_to
    );
    out.push_str("| Level | Seed | E | L | H | D |\n| --- | --- | --- | --- | --- | --- |\n");
    for (level, label) in LEVEL_NAMES.iter().enumerate() {
        for slot in 0..PER_LEVEL {
            let scored = scan.pick(level, slot);
            let candidate = &scored.candidate;
            let _ = writeln!(
                out,
                "| {label} | {} | {} | {} | {} | {:.4} |",
                candidate.seed,
                candidate.effort,
                candidate.length,
                u8::from(candidate.hint_win),
                scored.difficulty
            );
        }
    }
    out.push('\n');
}

const REPORT_INTRO: &str = "# Curated seeds (generated)

Generated by `cargo xtask-art curated-seeds` (decision T-49); do not edit by hand. Run it in a release
build: `cargo run --release -p xtask --features art -- curated-seeds`.

- Pool: seeds from 0 that the solver proves winnable at `SolveBudget::default_for(variant)`, until 60 are
  found, or seed 999 has passed with at least 15, or seed 4999 is reached.
- E: positions the solver generated (`solve_report().nodes`). L: moves of the verified winning list.
  H: 1 when `Game::hint()` alone wins the deal within 2,000 steps, else 0.
- D = 0.6 · pct(E) + 0.4 · pct(L) − 0.3 · H, where pct is the rank percentile within the pool.
- Levels: the pool sorted by D, cut into five equal quintiles (very easy first); in each, the three seeds
  nearest the quintile's median D.
";
